script.codigo_verbatim:
/* =========================================================
   INST 01 — MAPA FÍSICO
   ========================================================= */
var I1 = {
  nodes: [
    {id:'rr', x:255, y:52,  r:9,  nm:'Roraima', sub:'Norte',
     ger:'Último estado a se conectar ao sistema interligado, em setembro de 2025. Antes disso, atendimento por térmicas a óleo diesel e por importação de sistema vizinho. A linha que o conectou tem cerca de 725 quilômetros em circuito duplo de 500 quilovolts e custou aproximadamente R$ 2,6 bilhões.',
     esc:'Ponta de linha. A capacidade da conexão foi dimensionada em cerca de quatro vezes a demanda atual do estado, o que a torna também um caminho para escoar futuras hidrelétricas inventariadas na região. Quinze anos separaram a recomendação técnica da energização.'},
    {id:'am', x:212, y:112, r:11, nm:'Sistemas isolados da Amazônia', sub:'Norte',
     ger:'Menos de meio por cento da geração nacional, com perfil muito mais fóssil que a média — o diesel dominava a geração isolada em 2025. É a melhor demonstração de que média nacional esconde realidade local: o país é renovável e centenas de localidades não são.',
     esc:'Fora do sistema interligado por definição. A substituição do diesel exige solução confiável em todos os dias do ano, incluindo os de baixa irradiância, o que empurra qualquer alternativa para arranjos híbridos com armazenamento e respaldo.'},
    {id:'bm', x:300, y:135, r:14, nm:'Complexo do Xingu — Belo Monte', sub:'Norte',
     ger:'Grande hidrelétrica a fio d\'água, com capacidade elevada e forte sazonalidade de vazão. Contribui muito para a capacidade instalada nacional e menos para o armazenamento, porque não regulariza.',
     esc:'Escoada por elos dedicados de corrente contínua em alta tensão até o Sudeste, com entrega em pontos distintos da rede para distribuir o impacto. A arquitetura reduz perda em distância longa e cria dependência de estações conversoras — a perda de um bipolo é contingência de grande magnitude.'},
    {id:'tuc', x:340, y:150, r:11, nm:'Tucuruí e eixo Norte-Sul', sub:'Norte',
     ger:'Um dos maiores aproveitamentos hidrelétricos do país e ponto histórico de partida da integração nacional.',
     esc:'Origem do eixo Norte-Sul em corrente alternada, que transformou sistemas regionais numa rede nacional. Não é uma linha: é um conjunto de corredores e reforços cuja saturação divide eletricamente o país.'},
    {id:'mad', x:198, y:200, r:12, nm:'Complexo do Madeira', sub:'Norte',
     ger:'Duas grandes usinas a fio d\'água em Rondônia, com regime de vazão marcadamente sazonal e pouca capacidade de deslocar geração no tempo.',
     esc:'Escoada por bipolos de corrente contínua até o Sudeste, com mais de dois mil quilômetros. É o caso mais didático de por que corrente contínua existe: bloco grande, distância muito longa, fluxo controlável.'},
    {id:'nel', x:420, y:150, r:13, nm:'Eólicas do litoral — Rio Grande do Norte e Ceará', sub:'Nordeste',
     ger:'Um dos melhores recursos eólicos do mundo. Ventos fortes, regulares e com direção estável, o que produz fator de capacidade na faixa alta e previsibilidade acima da média internacional.',
     esc:'É onde a estabilidade de tensão limita o escoamento. Após a revisão dos modelos dinâmicos das usinas, a capacidade calculada de escoamento da região caiu, e compensadores síncronos passaram a ser indicados para restaurar parte dela.'},
    {id:'nei', x:400, y:200, r:13, nm:'Eólicas e solar do interior — Bahia e Piauí', sub:'Nordeste',
     ger:'Segundo polo de renovável variável, com eólica de interior e forte adição de solar centralizada. A coexistência das duas fontes no mesmo ponto de conexão amplia o volume e concentra o risco.',
     esc:'É a origem geográfica da maior parte do corte de geração brasileiro. A carga local é muito menor que o potencial de oferta em vários períodos, e o excedente depende inteiramente da capacidade de exportação.'},
    {id:'saf', x:428, y:238, r:11, nm:'São Francisco — Sobradinho e Paulo Afonso', sub:'Nordeste',
     ger:'Aproveitamentos hidrelétricos com regularização relevante, que dão ao Nordeste um estoque de energia próprio e uma capacidade de modulação que a eólica não tem.',
     esc:'Nó de articulação entre a geração renovável variável da região e o restante da malha. A operação desses reservatórios é condicionada por uso múltiplo da água — abastecimento, irrigação e navegação.'},
    {id:'exp', x:395, y:265, r:10, nm:'Fronteira de exportação Norte e Nordeste', sub:'Gargalo',
     ger:'Não é ponto de geração: é o limite através do qual a produção do Norte e do Nordeste alcança o maior centro de carga do país.',
     esc:'O gargalo estruturante do sistema brasileiro. O plano da operação de médio prazo projeta o limite de recebimento do Sudeste/Centro-Oeste evoluindo de 18.500 megawatts em janeiro de 2026 para 23.000 em janeiro de 2030, condicionado à entrada de obras.'},
    {id:'par', x:315, y:300, r:14, nm:'Bacia do Paraná — Grande e Paranaíba', sub:'Sudeste/Centro-Oeste',
     ger:'O coração do armazenamento brasileiro. O subsistema concentra cerca de setenta por cento da capacidade de armazenamento do país, e é por isso que a afluência dessas bacias é o número hidrológico que mais importa.',
     esc:'Destino da maioria dos intercâmbios e origem da exportação para o Sul. É também onde a geração hidráulica cumpre a função de equilibrar a rampa vespertina do sistema inteiro.'},
    {id:'sol', x:360, y:262, r:11, nm:'Solar centralizada — norte de Minas', sub:'Sudeste/Centro-Oeste',
     ger:'Polo de solar centralizada em crescimento acelerado, com irradiância elevada e proximidade relativa do maior centro de carga. Dá ao Sudeste uma assinatura diurna de geração que não existia há cinco anos.',
     esc:'Mais próxima da carga que a solar nordestina, o que reduz a exposição ao limite de exportação. Não elimina a exposição ao corte por razão energética, que é nacional e ocorre na mesma janela horária em todo o país.'},
    {id:'car', x:352, y:330, r:15, nm:'Centro de carga — São Paulo, Minas e Rio', sub:'Sudeste/Centro-Oeste',
     ger:'Onde está o consumo. Concentra indústria, serviços e população, e é o destino final da maior parte da energia produzida nos nós acima.',
     esc:'Recebe de todas as direções: do Norte por corrente contínua e por corrente alternada, do Nordeste pela fronteira de exportação, do Sul quando o Sul exporta, e da própria bacia do Paraná. A capacidade de <em>receber</em> é tão limitante quanto a de enviar.'},
    {id:'ita', x:300, y:368, r:12, nm:'Itaipu', sub:'Sul / Sudeste',
     ger:'Usina binacional criada por tratado. A parcela produzida para o país vizinho e adquirida pelo Brasil entra nas contas nacionais como eletricidade importada — motivo pelo qual a oferta interna de energia elétrica é maior que a geração nacional.',
     esc:'Escoada em corrente alternada e em corrente contínua, com sistemas dedicados. É o exemplo canônico de por que um número de matriz sempre depende de convenção estatística.'},
    {id:'sul', x:305, y:412, r:12, nm:'Sul — hidrelétricas e eólicas', sub:'Sul',
     ger:'Hidrologia própria e descolada das demais, com pouca regularização e alta volatilidade. Parque eólico relevante com regime distinto do nordestino, e carga industrial e agrícola forte.',
     esc:'O subsistema mais bidirecional: alterna importação e exportação conforme água, vento e carga. O plano de médio prazo projeta ampliação de cerca de vinte por cento na capacidade de recebimento a partir do Sudeste/Centro-Oeste.'}
  ],
  arrows: {
    esc: [['mad','par'],['bm','car'],['tuc','par'],['nel','exp'],['nei','exp'],['saf','exp'],['exp','car'],['sol','car'],['par','car'],['ita','car'],['car','sul'],['am','am'],['rr','am']],
    ger: [['nel','nei'],['nei','saf'],['bm','tuc'],['mad','par'],['sol','car'],['par','ita'],['ita','sul']]
  },
  cur: 'ger', sel: 'exp'
};
function i1render(){
  var svg = ['<svg viewBox="0 0 560 470" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto">'];
  svg.push('<path d="M170 90 L250 40 L330 55 L400 95 L470 150 L470 215 L430 265 L400 300 L385 355 L340 420 L285 450 L245 415 L225 355 L185 300 L150 235 L145 160 Z" fill="#15181E" stroke="#2E3440" stroke-width="1.2"/>');
  var byId = {};
  I1.nodes.forEach(function(n){ byId[n.id] = n; });
  var showE = (I1.cur === 'esc' || I1.cur === 'amb');
  var showG = (I1.cur === 'ger' || I1.cur === 'amb');
  function arrows(list, color, dash){
    list.forEach(function(p){
      var a = byId[p[0]], b = byId[p[1]];
      if(!a || !b || a === b) return;
      var mx = (a.x + b.x)/2 + (b.y - a.y)*0.12, my = (a.y + b.y)/2 - (b.x - a.x)*0.12;
      svg.push('<path d="M'+a.x+' '+a.y+' Q'+mx.toFixed(0)+' '+my.toFixed(0)+' '+b.x+' '+b.y+'" fill="none" stroke="'+color+'" stroke-width="1.6" opacity=".55"'+(dash?' stroke-dasharray="5 4"':'')+'/>');
    });
  }
  if(showG) arrows(I1.arrows.ger, '#10B981', true);
  if(showE) arrows(I1.arrows.esc, '#06B6D4', false);
  I1.nodes.forEach(function(n){
    var on = (n.id === I1.sel);
    var col = n.sub === 'Gargalo' ? '#EF4444' : (on ? '#F59E0B' : '#06B6D4');
    svg.push('<g class="mp-node" data-n="'+n.id+'" style="cursor:pointer">');
    svg.push('<circle cx="'+n.x+'" cy="'+n.y+'" r="'+(n.r+(on?5:0))+'" fill="'+col+'" opacity="'+(on?'.30':'.16')+'"/>');
    svg.push('<circle cx="'+n.x+'" cy="'+n.y+'" r="'+(on?6:4)+'" fill="'+col+'"/>');
    svg.push('</g>');
  });
  svg.push('</svg>');
  $id('i1-svg').innerHTML = svg.join('');
  $$('.mp-node', $id('i1-svg')).forEach(function(g){
    g.addEventListener('click', function(){ I1.sel = g.getAttribute('data-n'); i1render(); });
  });
  $id('i1-leg').innerHTML =
    '<span><i style="background:#06B6D4"></i>Corredor de escoamento</span>' +
    '<span><i style="background:#10B981"></i>Vizinhança de recurso</span>' +
    '<span><i style="background:#EF4444"></i>Gargalo estruturante</span>' +
    '<span><i style="background:#F59E0B"></i>Nó selecionado</span>';
  $id('i1-chips').innerHTML = I1.nodes.map(function(n){
    return '<span class="tl-chip'+(n.id===I1.sel?' on':'')+'" data-n="'+n.id+'">'+esc(n.nm)+'</span>';
  }).join('');
  $$('.tl-chip', $id('i1-chips')).forEach(function(c){
    c.addEventListener('click', function(){ I1.sel = c.getAttribute('data-n'); i1render(); });
  });
  var n = byId[I1.sel];
  var txt = I1.cur === 'ger' ? n.ger : (I1.cur === 'esc' ? n.esc :
    '<b>Geração.</b> ' + n.ger + '<br><br><b>Escoamento.</b> ' + n.esc);
  $id('i1-panel').innerHTML =
    '<div class="yr">'+esc(n.sub)+'</div><div class="ti">'+esc(n.nm)+'</div>' +
    '<div class="bd2">'+txt+'</div>' +
    '<div class="lg"><b>Fluxo em exibição</b><span>'+
    (I1.cur==='ger'?'Geração — onde o recurso está':(I1.cur==='esc'?'Escoamento — por onde a energia sai':'Os dois sobrepostos'))+'</span></div>';
}
segGroup('i1-seg', function(v){ I1.cur = v; i1render(); });
i1render();

/* =========================================================
   INST 02 — CONVERSOR DE TRÊS EIXOS
   ========================================================= */
var I2 = {
  src: [
    {k:'hid', nm:'Hidrelétrica',  cap:110.2, fc:41.6, col:'#06B6D4'},
    {k:'sol', nm:'Solar',         cap:64.8,  fc:15.5, col:'#F59E0B'},
    {k:'eol', nm:'Eólica',        cap:34.7,  fc:38.3, col:'#10B981'},
    {k:'bio', nm:'Biomassa',      cap:17.5,  fc:41.1, col:'#84CC16'},
    {k:'fos', nm:'Térmica fóssil',cap:31.8,  fc:27.5, col:'#EF4444'},
    {k:'nuc', nm:'Nuclear',       cap:2.0,   fc:90.4, col:'#A78BFA'}
  ]
};
function i2fields(){
  $id('i2-fields').innerHTML = I2.src.map(function(s){
    return '<div class="field"><div class="field-label"><span>'+esc(s.nm)+'</span><span class="unit">GW · FC %</span></div>' +
      '<div style="display:flex;gap:8px">' +
      '<input type="number" id="i2c-'+s.k+'" min="0" max="400" step="0.1" value="'+s.cap+'">' +
      '<input type="number" id="i2f-'+s.k+'" min="0" max="100" step="0.1" value="'+s.fc+'">' +
      '</div></div>';
  }).join('');
  I2.src.forEach(function(s){
    ['i2c-','i2f-'].forEach(function(p){
      var e = $id(p+s.k);
      e.addEventListener('input', function(){
        var v = clamp(e.value, Number(e.min), Number(e.max));
        if(p === 'i2c-') s.cap = v; else s.fc = v;
        i2calc();
      });
      e.addEventListener('blur', function(){ e.value = (p==='i2c-'? s.cap : s.fc); });
    });
  });
}
function pieSVG(items, total){
  var a = -Math.PI/2, out = ['<svg viewBox="0 0 180 180" width="160" height="160" xmlns="http://www.w3.org/2000/svg">'];
  if(total <= 0){ out.push('<circle cx="90" cy="90" r="72" fill="#1B1F27"/>'); }
  items.forEach(function(it){
    var frac = it.v/total; if(frac <= 0) return;
    var b = a + frac*Math.PI*2;
    if(frac > 0.9999){ out.push('<circle cx="90" cy="90" r="72" fill="'+it.col+'"/>'); a = b; return; }
    var x1 = 90+72*Math.cos(a), y1 = 90+72*Math.sin(a);
    var x2 = 90+72*Math.cos(b), y2 = 90+72*Math.sin(b);
    out.push('<path d="M90 90 L'+x1.toFixed(2)+' '+y1.toFixed(2)+' A72 72 0 '+(frac>0.5?1:0)+' 1 '+x2.toFixed(2)+' '+y2.toFixed(2)+' Z" fill="'+it.col+'" stroke="#0C0D10" stroke-width="1.5"/>');
    a = b;
  });
  out.push('<circle cx="90" cy="90" r="34" fill="#15181E" stroke="#242832"/></svg>');
  return out.join('');
}
function i2calc(){
  var A = I2.src.map(function(s){ return {nm:s.nm, col:s.col, v:s.cap, k:s.k}; });
  var B = I2.src.map(function(s){ return {nm:s.nm, col:s.col, v:s.cap*(s.fc/100)*8.76, k:s.k}; });
  var tA = A.reduce(function(a,b){ return a+b.v; },0);
  var tB = B.reduce(function(a,b){ return a+b.v; },0);
  var rA = A.slice().sort(function(a,b){ return b.v-a.v; });
  var rB = B.slice().sort(function(a,b){ return b.v-a.v; });
  var posA = {}, posB = {};
  rA.forEach(function(x,i){ posA[x.k] = i+1; });
  rB.forEach(function(x,i){ posB[x.k] = i+1; });
  $id('i2-pieA').innerHTML = pieSVG(rA, tA);
  $id('i2-pieB').innerHTML = pieSVG(rB, tB);
  function legend(rank, tot, pos, other){
    return rank.map(function(x){
      var moved = pos[x.k] !== other[x.k];
      return '<div><i style="background:'+x.col+'"></i><b>'+esc(x.nm)+'</b> · '+
        (tot>0? f1(x.v/tot*100) : '0,0')+'%'+(moved?' <span class="swap">↔ trocou</span>':'')+'</div>';
    }).join('');
  }
  $id('i2-lgA').innerHTML = legend(rA, tA, posA, posB);
  $id('i2-lgB').innerHTML = legend(rB, tB, posB, posA);
  var trocas = I2.src.filter(function(s){ return posA[s.k] !== posB[s.k]; });
  var maiorSubida = null, maiorQueda = null;
  I2.src.forEach(function(s){
    var pa = tA>0 ? s.cap/tA*100 : 0;
    var pb = tB>0 ? (s.cap*(s.fc/100)*8.76)/tB*100 : 0;
    var d = pb - pa;
    if(!maiorSubida || d > maiorSubida.d) maiorSubida = {nm:s.nm, d:d};
    if(!maiorQueda || d < maiorQueda.d) maiorQueda = {nm:s.nm, d:d};
  });
  $id('i2-out').innerHTML =
    '<div class="ro"><div class="k">Capacidade total</div><div class="n">'+f1(tA)+'<span class="u">GW</span></div></div>' +
    '<div class="ro"><div class="k">Geração implícita</div><div class="n">'+f0(tB)+'<span class="u">TWh/ano</span></div></div>' +
    '<div class="ro"><div class="k">Fator de capacidade médio</div><div class="n gold">'+(tA>0? f1(tB/(tA*8.76)*100):'0,0')+'<span class="u">%</span></div></div>' +
    '<div class="ro"><div class="k">Fontes que trocam de posição</div><div class="n">'+trocas.length+'</div></div>';
  var vd = $id('i2-vd'), cls, msg;
  if(trocas.length === 0){
    cls = 'att';
    msg = '<b>Nenhuma troca de posição.</b> Isso só acontece quando os fatores de capacidade digitados são muito próximos entre si. É um cenário útil como teste: se todas as fontes tivessem o mesmo fator, as duas pizzas seriam idênticas e este bloco inteiro seria desnecessário. Volte um fator para um valor realista e observe o ranking se reorganizar.';
  } else if(trocas.length <= 2){
    cls = 'ok';
    msg = '<b>'+trocas.length+' troca'+(trocas.length>1?'s':'')+' de posição.</b> A fonte que mais ganha participação ao passar de capacidade para geração é <b>'+esc(maiorSubida.nm)+'</b>, com '+f1(maiorSubida.d)+' pontos percentuais de ganho; a que mais perde é <b>'+esc(maiorQueda.nm)+'</b>, com '+f1(Math.abs(maiorQueda.d))+' pontos de perda. A direção do movimento é inteiramente previsível pelo fator de capacidade de cada fonte em relação à média do parque — quem está acima da média sobe, quem está abaixo desce.';
  } else {
    cls = 'per';
    msg = '<b>'+trocas.length+' trocas de posição.</b> Este é o cenário que torna qualquer afirmação sobre "a segunda maior fonte do Brasil" indefensável sem qualificação. Com essa dispersão de fatores de capacidade, o ranking da pizza de capacidade e o da pizza de geração são objetos diferentes, e citar um como se fosse o outro produz um erro que não é de arredondamento — é de ordem. A fonte que mais sobe é <b>'+esc(maiorSubida.nm)+'</b> e a que mais desce é <b>'+esc(maiorQueda.nm)+'</b>.';
  }
  vd.className = 'verdict ' + cls;
  vd.innerHTML = msg;
}
i2fields(); i2calc();

/* =========================================================
   INST 03 — CALCULADORA DE FATOR DE CAPACIDADE
   ========================================================= */
var I3 = {
  s: 'hid',
  faixas: {
    hid:{nm:'Hidrelétrica', lo:40, hi:60,
      baixo:'Para hidrelétrica, fator abaixo da faixa sugere ano hidrológico fraco, usina a fio d\'água em período de vazão baixa, restrição de uso múltiplo da água, ou decisão de despacho que preservou reservatório. Raramente indica problema de equipamento.',
      alto:'Acima da faixa é possível em ano de afluência muito favorável ou em usina operando próximo do máximo por posição na cascata. Verifique se o denominador não está subestimado — capacidade fiscalizada divergente da outorgada é a causa mais comum.'},
    eol:{nm:'Eólica', lo:35, hi:50,
      baixo:'Para eólica, fator abaixo da faixa aponta para quatro suspeitos, nesta ordem de frequência: corte de geração por restrição, indisponibilidade de turbinas, recurso de sítio abaixo do estimado no projeto, e entrada em operação ao longo do período inflando o denominador. Separar corte de recurso é a primeira coisa a fazer.',
      alto:'Acima da faixa é plausível em sítios excepcionais do Nordeste, especialmente no segundo semestre. Se o valor for anual e muito alto, confirme se a série não está medida na barra sem descontar perdas.'},
    sol:{nm:'Solar', lo:20, hi:30,
      baixo:'Para solar, fator abaixo da faixa quase sempre tem causa aritmética antes de ter causa física: usar a potência de fim de período como denominador de uma usina que entrou em operação durante o ano. Depois disso, investigue sujidade, degradação, indisponibilidade de inversor e corte de geração.',
      alto:'Acima da faixa é raro para fotovoltaica fixa. Verifique se a potência informada é de módulos ou de inversores — a razão entre as duas muda o resultado — e se há rastreamento solar no arranjo.'},
    bio:{nm:'Biomassa', lo:35, hi:55,
      baixo:'Para biomassa, fator baixo é o comportamento esperado fora da safra, e não indica problema. A leitura correta separa o período de safra do período de entressafra em vez de calcular o fator anual, que mistura dois regimes distintos.',
      alto:'Acima da faixa sugere operação com combustível complementar fora da safra, ou cogeração com processo industrial contínuo. Confirme se a energia informada é a exportada para a rede ou a total gerada, incluindo o consumo da própria planta.'},
    gas:{nm:'Gás natural', lo:15, hi:70,
      baixo:'Para térmica a gás, fator baixo é frequentemente sinal de sistema saudável: a usina existe para os momentos em que o sistema precisa dela, e não ser acionada significa que a hidrologia foi boa. A pergunta relevante não é por que gerou pouco, é se estava disponível quando foi chamada.',
      alto:'Acima da faixa indica despacho prolongado, típico de ano hidrológico ruim, ou inflexibilidade contratual que obriga a geração independentemente da ordem de mérito. As duas causas têm implicações econômicas opostas e precisam ser distinguidas.'},
    nuc:{nm:'Nuclear', lo:75, hi:92,
      baixo:'Para nuclear, fator abaixo da faixa aponta para parada programada de reabastecimento ou manutenção prolongada dentro do período. Em base anual, uma parada de algumas semanas já desloca o valor vários pontos.',
      alto:'Acima da faixa é o comportamento de referência de operação em base sem parada no período. É o maior fator de capacidade do parque brasileiro e serve de teto prático para leitura comparativa.'}
  }
};
var i3get = {};
function i3calc(){
  var p = i3get.p(), e = i3get.e(), h = i3get.h();
  var teor = p * h / 1000;
  var fc = teor > 0 ? (e / teor) * 100 : 0;
  var fx = I3.faixas[I3.s];
  var horasEq = p > 0 ? (e*1000)/p : 0;
  $id('i3-out').innerHTML =
    '<div class="ro"><div class="k">Energia teórica máxima</div><div class="n">'+f0(teor)+'<span class="u">GWh</span></div></div>' +
    '<div class="ro"><div class="k">Fator de capacidade</div><div class="n gold">'+f1(fc)+'<span class="u">%</span></div></div>' +
    '<div class="ro"><div class="k">Horas equivalentes a plena carga</div><div class="n">'+f0(horasEq)+'<span class="u">h</span></div></div>' +
    '<div class="ro"><div class="k">Faixa típica · '+esc(fx.nm)+'</div><div class="n sm">'+fx.lo+'% a '+fx.hi+'%</div></div>';
  var vd = $id('i3-vd'), cls, msg;
  if(fc > 100){
    cls = 'per';
    msg = '<b>Fator acima de 100% — impossível fisicamente.</b> A energia informada excede a que a potência declarada consegue produzir no período. Três causas cobrem quase todos os casos: unidade trocada entre MWh e GWh, período menor que o efetivo de geração, ou potência informada abaixo da real. Antes de investigar qualquer coisa no ativo, confira as unidades.';
  } else if(fc < fx.lo){
    cls = 'att';
    msg = '<b>Abaixo da faixa típica de '+esc(fx.nm)+'.</b> ' + fx.baixo + ' Lembre que o fator de capacidade é sintoma, não diagnóstico: ele mistura recurso, disponibilidade, despacho e restrição numa razão só, e separar essas causas exige a série horária, não o total do período.';
  } else if(fc > fx.hi){
    cls = 'att';
    msg = '<b>Acima da faixa típica de '+esc(fx.nm)+'.</b> ' + fx.alto + ' Um valor fora da faixa é sinal para investigar, nunca prova de erro — as faixas são ordens de grandeza para leitura rápida, não parâmetros de projeto.';
  } else {
    cls = 'ok';
    msg = '<b>Dentro da faixa típica de '+esc(fx.nm)+'.</b> As '+f0(horasEq)+' horas equivalentes a plena carga são a tradução mais intuitiva do resultado: é como se a usina tivesse operado no máximo durante esse número de horas e ficado parada no resto do período. Guarde essa leitura — ela torna a comparação entre fontes imediata sem precisar de percentual.';
  }
  vd.className = 'verdict ' + cls;
  vd.innerHTML = msg;
}
