script.codigo_verbatim:
/* =========================================================
   INST 04 — RECONSTRUTOR DE MATRIZ
   ========================================================= */
var I4 = {
  r: 'cap',
  fontes: [
    {k:'hid', nm:'Hidrelétrica'},
    {k:'sol', nm:'Solar'},
    {k:'eol', nm:'Eólica'},
    {k:'bio', nm:'Biomassa'},
    {k:'fos', nm:'Térmica fóssil'},
    {k:'nuc', nm:'Nuclear'}
  ],
  ref: {cap:{hid:42.2, sol:24.8, eol:13.3, bio:6.7, fos:12.2, nuc:0.8},
        ger:{hid:51.7, sol:11.4, eol:15.0, bio:8.1, fos:11.8, nuc:2.0}},
  pal: {cap:{}, ger:{}},
  tol: 3
};
function i4inputs(){
  $id('i4-inputs').innerHTML = '<div class="field-grid">' + I4.fontes.map(function(f){
    var v = I4.pal[I4.r][f.k];
    return '<div class="field"><div class="field-label"><span>'+esc(f.nm)+'</span><span class="unit">% da pizza</span></div>' +
      '<input type="number" id="i4i-'+f.k+'" min="0" max="100" step="0.1" value="'+(v===undefined?'':v)+'" placeholder="—"></div>';
  }).join('') + '</div>';
  I4.fontes.forEach(function(f){
    var e = $id('i4i-'+f.k);
    e.addEventListener('input', function(){
      if(e.value === ''){ delete I4.pal[I4.r][f.k]; return; }
      I4.pal[I4.r][f.k] = clamp(e.value, 0, 100);
    });
  });
  $id('i4-ref').innerHTML = ['cap','ger'].map(function(r){
    return I4.fontes.map(function(f){
      return '<div class="field"><div class="field-label"><span>'+esc(f.nm)+'</span><span class="unit">'+(r==='cap'?'capacidade':'geração')+' %</span></div>' +
        '<input type="number" id="i4r-'+r+'-'+f.k+'" min="0" max="100" step="0.1" value="'+I4.ref[r][f.k]+'"></div>';
    }).join('');
  }).join('');
  ['cap','ger'].forEach(function(r){
    I4.fontes.forEach(function(f){
      var e = $id('i4r-'+r+'-'+f.k);
      e.addEventListener('input', function(){ I4.ref[r][f.k] = clamp(e.value, 0, 100); });
      e.addEventListener('blur', function(){ e.value = I4.ref[r][f.k]; });
    });
  });
}
function i4check(){
  var pal = I4.pal[I4.r], ref = I4.ref[I4.r];
  var faltando = I4.fontes.filter(function(f){ return pal[f.k] === undefined; });
  var vd = $id('i4-vd');
  if(faltando.length){
    $id('i4-res').innerHTML = '';
    vd.className = 'verdict att';
    vd.innerHTML = '<b>Faltam '+faltando.length+' estimativa'+(faltando.length>1?'s':'')+'.</b> Preencha todas as seis antes de corrigir. Chutar é parte do exercício: o objetivo não é acertar, é descobrir em que direção você erra — e para isso o instrumento precisa de todas as fatias.';
    return;
  }
  var soma = I4.fontes.reduce(function(a,f){ return a + pal[f.k]; }, 0);
  var rows = [], errTotal = 0, acertos = 0, superest = [], subest = [];
  I4.fontes.forEach(function(f){
    var d = pal[f.k] - ref[f.k];
    errTotal += Math.abs(d);
    if(Math.abs(d) <= I4.tol) acertos++;
    else if(d > 0) superest.push(f.nm); else subest.push(f.nm);
    var w = Math.min(50, Math.abs(d)/30*50);
    var cls = Math.abs(d) <= I4.tol ? '' : (d > 0 ? ' over' : ' under');
    var style = d >= 0 ? 'left:50%;width:'+w+'%' : 'right:50%;width:'+w+'%';
    rows.push('<div class="err-row"><div class="err-nm">'+esc(f.nm)+'</div>' +
      '<div class="err-bar"><div class="err-mid"></div><div class="err-fill'+cls+'" style="'+style+'"></div></div>' +
      '<div class="err-v'+(Math.abs(d)>I4.tol?' big':'')+'">'+(d>=0?'+':'−')+f1(Math.abs(d))+' pp</div></div>');
  });
  var ordPal = I4.fontes.slice().sort(function(a,b){ return pal[b.k]-pal[a.k]; }).map(function(f){ return f.k; }).join(',');
  var ordRef = I4.fontes.slice().sort(function(a,b){ return ref[b.k]-ref[a.k]; }).map(function(f){ return f.k; }).join(',');
  var ordemOk = ordPal === ordRef;
  $id('i4-res').innerHTML =
    '<div class="readout" style="margin-top:18px">' +
    '<div class="ro"><div class="k">Fontes dentro da tolerância</div><div class="n">'+acertos+'<span class="u">de 6</span></div></div>' +
    '<div class="ro"><div class="k">Erro absoluto total</div><div class="n gold">'+f1(errTotal)+'<span class="u">pp</span></div></div>' +
    '<div class="ro"><div class="k">Sua soma</div><div class="n">'+f1(soma)+'<span class="u">%</span></div></div>' +
    '<div class="ro"><div class="k">Ordem das fontes</div><div class="n sm">'+(ordemOk?'Correta':'Incorreta')+'</div></div>' +
    '</div><div style="margin-top:14px">'+rows.join('')+'</div>';
  var cls, msg = '';
  if(Math.abs(soma-100) > 8){
    cls = 'per';
    msg = '<b>A soma das suas fatias é '+f1(soma)+'%, não 100%.</b> Antes de qualquer diagnóstico de conteúdo, corrija isso — uma pizza que não fecha em cem por cento não é uma estimativa da matriz, é uma lista de palpites independentes. Use o botão de normalizar e observe como as fatias se reorganizam: essa reorganização já ensina metade do exercício, porque mostra quais fontes você estava inflando sem perceber.';
  } else if(ordemOk && acertos === 6){
    cls = 'ok';
    msg = '<b>Reconstrução correta.</b> Ordem certa e todas as seis fatias dentro da tolerância de '+I4.tol+' pontos. Isso é o critério oficial de domínio deste bloco cumprido para a pizza de '+(I4.r==='cap'?'capacidade':'geração')+'. Faça a outra rodada e, ao terminar, explique em voz alta cada troca de posição entre as duas — é a explicação, não o acerto, que consolida.';
  } else if(ordemOk){
    cls = 'ok';
    msg = '<b>Ordem correta, com '+(6-acertos)+' fatia'+((6-acertos)>1?'s':'')+' fora da tolerância.</b> Isso é aprovação no critério que importa. A ordem e a ordem de grandeza são conhecimento durável; o decimal tem prazo de validade de um ano e você deve consultá-lo, não decorá-lo. Se quiser fechar o exercício por completo, revise apenas as fontes marcadas em vermelho — mas não gaste tempo memorizando os valores exatos.';
  } else {
    cls = 'per';
    msg = '<b>A ordem das fontes está incorreta.</b> Esse é o erro que importa neste bloco, e é bem mais grave que errar decimal. A ordem é o que você usa numa conversa sem consultar nada, e é o que impede a frase indefensável do tipo "a segunda maior fonte do Brasil". Refaça esta rodada olhando as fichas da Aula 02, com atenção especial ao fator de capacidade de cada fonte — é ele que determina a posição em cada uma das duas pizzas.';
  }
  if(superest.length || subest.length){
    msg += '<br><br><b>Diagnóstico do seu viés.</b> ';
    if(superest.length) msg += 'Você superestimou: ' + superest.join(', ') + '. ';
    if(subest.length) msg += 'Você subestimou: ' + subest.join(', ') + '. ';
    if(I4.r === 'cap' && subest.indexOf('Térmica fóssil') >= 0){
      msg += 'Subestimar a térmica em capacidade é o viés mais comum e tem causa identificável: como ela gera pouco em ano bom, a intuição a encolhe. Ela é maior do que parece justamente porque existe para os anos ruins — capacidade que raramente é usada continua sendo capacidade.';
    }
    if(I4.r === 'ger' && superest.indexOf('Solar') >= 0){
      msg += 'Superestimar a solar em geração é o segundo viés mais comum. Ela é a fonte mais visível, a que mais aparece em notícia e a que mais cresce em potência, e essa saliência empurra a estimativa de energia para cima. O corretivo é lembrar que o recurso só existe durante parte do dia.';
    }
    if(I4.r === 'ger' && subest.indexOf('Hidrelétrica') >= 0){
      msg += 'Subestimar a hidrelétrica em geração costuma vir de exposição excessiva à narrativa de expansão renovável variável. A hidro perdeu participação por diluição, não por encolhimento: a fatia caiu porque a pizza cresceu.';
    }
  }
  vd.className = 'verdict ' + cls;
  vd.innerHTML = msg;
}
segGroup('i4-seg', function(v){ I4.r = v; i4inputs(); $id('i4-res').innerHTML=''; 
  var vd = $id('i4-vd'); vd.className = 'verdict att';
  vd.innerHTML = '<b>Rodada de '+(v==='cap'?'capacidade instalada':'geração efetiva')+'.</b> ' +
    (v==='cap' ? 'Estime a fatia de cada fonte na potência nominal instalada, no conceito amplo — incluindo geração distribuída e autoprodução. Pense em tamanho de parque, não em energia produzida.'
               : 'Agora estime a fatia de cada fonte na energia efetivamente produzida ao longo de um ano. Se você repetir os mesmos números da rodada anterior, vai errar sistematicamente — e o padrão do erro é exatamente o que o instrumento existe para revelar.');
});
$id('i4-go').addEventListener('click', i4check);
$id('i4-norm').addEventListener('click', function(){
  var pal = I4.pal[I4.r];
  var s = I4.fontes.reduce(function(a,f){ return a + (pal[f.k]||0); }, 0);
  if(s <= 0) return;
  I4.fontes.forEach(function(f){ pal[f.k] = Math.round((pal[f.k]||0)/s*1000)/10; });
  i4inputs(); i4check();
});
$id('i4-rst').addEventListener('click', function(){
  I4.pal = {cap:{}, ger:{}}; i4inputs(); $id('i4-res').innerHTML = '';
  var vd = $id('i4-vd'); vd.className = 'verdict att';
  vd.innerHTML = '<b>Zerado.</b> Comece pela rodada de capacidade instalada, sem consultar as fichas. O erro é o dado que interessa aqui.';
});
i4inputs();
(function(){ var vd = $id('i4-vd'); vd.className = 'verdict att';
  vd.innerHTML = '<b>Rodada de capacidade instalada.</b> Estime a fatia de cada fonte na potência nominal instalada, no conceito amplo — incluindo geração distribuída e autoprodução. Pense em tamanho de parque, não em energia produzida.'; })();

/* =========================================================
   INST 05 — LEITURA LATERAL
   ========================================================= */
var I5 = {
  campos: [
    {k:'cap', nm:'Participação em capacidade'},
    {k:'ger', nm:'Participação em geração'},
    {k:'fc',  nm:'Fator de capacidade típico'},
    {k:'geo', nm:'Concentração geográfica'},
    {k:'saz', nm:'Perfil sazonal'},
    {k:'dia', nm:'Perfil intradiário'},
    {k:'cre', nm:'O que a faz crescer ou parar'}
  ],
  sel: 'saz',
  dados: {
    'Hidrelétrica': {
      cap:'A maior fatia isolada, mas abaixo da metade — cerca de 42% no conceito amplo, contra mais de metade uma década antes.',
      ger:'Cerca de 52%. Sobe dez pontos ao trocar de pizza: o maior salto absoluto de todas as fontes, e a razão de a hidráulica continuar sendo descrita como a base do sistema mesmo tendo caído abaixo da metade em capacidade.',
      fc:'Faixa de 45% a 60%, com forte variação interanual. Não é limitação técnica: é despacho somado à hidrologia.',
      geo:'Armazenamento na bacia do Paraná; grandes usinas a fio d\'água no Norte; São Francisco no Nordeste; Iguaçu e Uruguai no Sul.',
      saz:'Segue o regime de chuvas de cada bacia. Úmido de novembro a abril no Sudeste/Centro-Oeste. A diversidade entre bacias é o que a integração nacional existe para aproveitar.',
