function i6render(){
  var d = I6.dados[I6.e], lb = I6.eixos[I6.e];
  var W = 700, H = 300, ml = 42, mr = 12, mt = 14, mb = 26;
  var pw = W-ml-mr, ph = H-mt-mb, n = 12;
  var maxV = 100;
  function X(i){ return ml + (i/(n-1))*pw; }
  function Y(v){ return mt + ph - (v/maxV)*ph; }
  var s = ['<svg viewBox="0 0 '+W+' '+H+'" xmlns="http://www.w3.org/2000/svg">'];
  for(var g=0; g<=4; g++){
    var yv = g*25, y = Y(yv);
    s.push('<line x1="'+ml+'" y1="'+y.toFixed(1)+'" x2="'+(W-mr)+'" y2="'+y.toFixed(1)+'" stroke="#242832" stroke-width="1"/>');
    s.push('<text x="'+(ml-8)+'" y="'+(y+3).toFixed(1)+'" fill="#6E7686" font-size="9" text-anchor="end">'+yv+'</text>');
  }
  lb.forEach(function(l,i){
    s.push('<text x="'+X(i).toFixed(1)+'" y="'+(H-8)+'" fill="#6E7686" font-size="9" text-anchor="middle">'+l+'</text>');
  });
  var soma = [];
  for(var i=0;i<n;i++){
    var t = 0;
    Object.keys(I6.on).forEach(function(k){ if(I6.on[k]) t += d[k][i]; });
    soma.push(t);
  }
  var exc = [];
  for(i=0;i<n;i++){ exc.push(Math.max(0, soma[i]-d.liq[i])); }
  var pts = [];
  for(i=0;i<n;i++){ if(soma[i] > d.liq[i]) pts.push(i); }
  if(pts.length){
    var poly = [];
    for(i=0;i<n;i++){ poly.push(X(i).toFixed(1)+','+Y(Math.max(soma[i], d.liq[i])).toFixed(1)); }
    for(i=n-1;i>=0;i--){ poly.push(X(i).toFixed(1)+','+Y(d.liq[i]).toFixed(1)); }
    s.push('<polygon points="'+poly.join(' ')+'" fill="#EF4444" opacity=".16"/>');
  }
  function line(arr, col, w, dash){
    var p = arr.map(function(v,i){ return (i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1); }).join(' ');
    s.push('<path d="'+p+'" fill="none" stroke="'+col+'" stroke-width="'+w+'"'+(dash?' stroke-dasharray="6 4"':'')+' stroke-linejoin="round"/>');
  }
  Object.keys(I6.on).forEach(function(k){ if(I6.on[k]) line(d[k], I6.cor[k], 1.7); });
  line(soma, '#A78BFA', 2.2);
  line(d.carga, '#E6E8EC', 2.2);
  line(d.liq, '#E6E8EC', 1.6, true);
  s.push('</svg>');
  $id('i6-svg').innerHTML = s.join('');
  $id('i6-src').innerHTML = Object.keys(I6.on).map(function(k){
    return '<span class="src-t'+(I6.on[k]?' on':'')+'" data-k="'+k+'" style="'+(I6.on[k]?'color:'+I6.cor[k]:'')+'"><i style="background:'+I6.cor[k]+'"></i>'+I6.nm[k]+'</span>';
  }).join('') + '<span class="src-t on" style="color:#A78BFA"><i style="background:#A78BFA"></i>Soma das ligadas</span>' +
    '<span class="src-t on" style="color:#E6E8EC"><i style="background:#E6E8EC"></i>Carga e carga líquida</span>';
  $$('.src-t[data-k]', $id('i6-src')).forEach(function(t){
    t.addEventListener('click', function(){
      var k = t.getAttribute('data-k'); I6.on[k] = !I6.on[k]; i6render();
    });
  });
  var horasExc = exc.filter(function(v){ return v > 0; }).length;
  var maxExc = Math.max.apply(null, exc);
  var deficit = [];
  for(i=0;i<n;i++){ deficit.push(Math.max(0, d.carga[i]-soma[i])); }
  var maxDef = Math.max.apply(null, deficit);
  var ligadas = Object.keys(I6.on).filter(function(k){ return I6.on[k]; }).length;
  $id('i6-out').innerHTML =
    '<div class="ro"><div class="k">Fontes ligadas</div><div class="n">'+ligadas+'<span class="u">de 5</span></div></div>' +
    '<div class="ro"><div class="k">Pontos com excedente</div><div class="n'+(horasExc?' gold':'')+'">'+horasExc+'<span class="u">de 12</span></div></div>' +
    '<div class="ro"><div class="k">Maior excedente</div><div class="n">'+f0(maxExc)+'<span class="u">un.</span></div></div>' +
    '<div class="ro"><div class="k">Maior déficit contra a carga</div><div class="n">'+f0(maxDef)+'<span class="u">un.</span></div></div>';
  var vd = $id('i6-vd'), cls, msg = I6.txt[I6.e] + '<br><br>';
  if(ligadas === 0){
    cls = 'per';
    msg += '<b>Nenhuma fonte ligada.</b> A distância inteira entre a linha de carga e o eixo é o que precisa ser atendido. Ligue as fontes uma a uma, na ordem em que quiser, e observe qual parte da curva cada uma cobre — e qual parte nenhuma delas cobre.';
  } else if(horasExc === 0){
    cls = 'ok';
    msg += '<b>Sem excedente nesta configuração.</b> Toda a geração das fontes ligadas cabe abaixo da carga líquida em todos os pontos. Esse é o estado em que o sistema opera sem precisar cortar ninguém — e note que ele deixa de existir assim que você liga a solar na escala diária de domingo.';
  } else if(horasExc <= 3){
    cls = 'att';
    msg += '<b>Excedente em '+horasExc+' ponto'+(horasExc>1?'s':'')+'.</b> A área vermelha é energia disponível que não tem para onde ir. Nesta magnitude, ela ainda é administrável com redução das fontes despacháveis e ajuste de intercâmbio. O que muda o caráter do problema não é o tamanho do excedente — é a frequência com que ele aparece.';
  } else {
    cls = 'per';
    msg += '<b>Excedente em '+horasExc+' dos 12 pontos.</b> Nesta frequência, o excedente deixa de ser evento e vira regime. A área vermelha representa energia que precisa ser cortada por razão energética, e reforço de transmissão não a elimina — ela existiria mesmo com rede infinita, porque não há carga em lugar nenhum do país naquela hora. As soluções que atacam esse regime são armazenamento, flexibilidade de demanda e moderação da expansão correlacionada.';
  }
  vd.className = 'verdict ' + cls;
  vd.innerHTML = msg;
}
