/* =========================================================
   INST 10 — PERFIL DE CARGA
   ========================================================= */
var i10get = {};
function i10calc(){
  var c = i10get.c(), h = i10get.h(), d = i10get.d(), t = i10get.t();
  var horasAno = h * d * 52;
  var demMed = horasAno > 0 ? (c*1000)/horasAno : 0;
  var demMedAnual = c*1000/8760;
  var fatorCarga = demMed > 0 ? (demMedAnual/demMed)*100 : 0;
  var horasDiurnas = Math.min(h, 7);
  var energiaDiurna = c * (t/100);
  var potDiurna = (horasDiurnas*d*52) > 0 ? (energiaDiurna*1000)/(horasDiurnas*d*52) : 0;
  var coberturaSolar = demMed > 0 ? Math.min(100, (potDiurna/demMed)*100*(horasDiurnas/Math.max(h,1))) : 0;
  $id('i10-out').innerHTML =
    '<div class="ro"><div class="k">Demanda média em operação</div><div class="n">'+f1(demMed)+'<span class="u">MW</span></div></div>' +
    '<div class="ro"><div class="k">Fator de carga anual</div><div class="n gold">'+f1(fatorCarga)+'<span class="u">%</span></div></div>' +
    '<div class="ro"><div class="k">Horas de operação por ano</div><div class="n">'+f0(horasAno)+'<span class="u">h</span></div></div>' +
    '<div class="ro"><div class="k">Cobertura solar teórica</div><div class="n">'+f0(coberturaSolar)+'<span class="u">%</span></div></div>';
  var vd = $id('i10-vd'), cls, msg;
  if(fatorCarga >= 85){
    cls = 'ok';
    msg = '<b>Perfil praticamente contínuo, fator de carga de '+f1(fatorCarga)+'%.</b> É o perfil típico de mineração, metalurgia, química de base e papel e celulose. A boa notícia: demanda contratada bem aproveitada e previsibilidade alta. A notícia relevante: praticamente nenhuma flexibilidade natural, o que significa que participação em resposta da demanda exige alteração de processo, não apenas de agenda. ';
  } else if(fatorCarga >= 55){
    cls = 'ok';
    msg = '<b>Perfil de operação estendida, fator de carga de '+f1(fatorCarga)+'%.</b> Turnos longos com paradas definidas. Há espaço real para deslocar processos não críticos — refrigeração, bombeamento, carregamento de baterias, moagem — para janelas específicas, e esse espaço tem valor econômico mensurável. ';
  } else if(fatorCarga >= 30){
    cls = 'att';
    msg = '<b>Perfil concentrado, fator de carga de '+f1(fatorCarga)+'%.</b> A planta consome muito em poucas horas. A consequência direta é que a demanda contratada precisa cobrir um pico que existe numa fração pequena do tempo, e o custo dessa capacidade ociosa é frequentemente a maior oportunidade de otimização de uma conta industrial. ';
  } else {
    cls = 'per';
    msg = '<b>Perfil altamente concentrado, fator de carga de '+f1(fatorCarga)+'%.</b> Este é o perfil que mais penaliza economicamente, porque exige capacidade instalada e contratada dimensionada para um pico que ocorre raramente. Antes de qualquer discussão sobre fonte ou contrato, a pergunta é se o pico pode ser achatado — deslocar carga costuma valer mais que negociar preço. ';
  }
  if(t >= 70 && horasDiurnas >= 6){
    msg += '<br><br><b>Casamento com solar.</b> Com '+f0(t)+'% do consumo concentrado no turno diurno, o perfil tem afinidade estrutural com geração fotovoltaica: a produção e o consumo ocorrem na mesma janela. É o caso menos comum na indústria pesada e o mais comum em comércio, serviços e agroindústria de beneficiamento.';
  } else if(t <= 35){
    msg += '<br><br><b>Descasamento com solar.</b> Com apenas '+f0(t)+'% do consumo no turno diurno, contratar exclusivamente solar deixa a maior parte da operação descoberta nas horas em que ela realmente consome. Isso não invalida a fonte — invalida a leitura de que basta comparar volume anual. A pergunta correta é qual fração do consumo cai dentro da janela de produção, e a resposta aqui é pequena.';
  } else {
    msg += '<br><br><b>Casamento parcial com solar.</b> Com '+f0(t)+'% do consumo no turno diurno, a fonte cobre uma parte relevante e deixa o resto exposto. É a configuração mais comum e a mais mal analisada, porque o volume anual sugere um casamento melhor do que o perfil horário confirma.';
  }
  if(h >= 20 && d >= 6){
    msg += ' Operação praticamente ininterrupta também significa que o custo de uma interrupção não programada é alto: a confiabilidade local da distribuidora deixa de ser detalhe e vira variável de decisão independente do preço da energia.';
  }
  msg += '<br><br><span style="color:#6E7686">Este instrumento não trata de estrutura tarifária, modalidade nem posto horário, que são matéria do Bloco 10. Ele responde apenas à pergunta de formato: qual é a forma da curva e com qual fonte ela conversa.</span>';
  vd.className = 'verdict ' + cls;
  vd.innerHTML = msg;
}
i10get.c = pairSlider('i10-c','i10-cn', i10calc);
i10get.h = pairSlider('i10-h','i10-hn', i10calc);
i10get.d = pairSlider('i10-d','i10-dn', i10calc);
i10get.t = pairSlider('i10-t','i10-tn', i10calc);
i10calc();

